class Solution {
public:
    int leastBricks(vector<vector<int>>& wall) {
        unordered_map<long long, int> edgeCount;
        int maxEdges = 0;
        int n = (int)wall.size();
        for (auto& row : wall) {
            long long pos = 0;
            for (size_t i = 0; i + 1 < row.size(); i++) {
                pos += row[i];
                edgeCount[pos]++;
                if (edgeCount[pos] > maxEdges) {
                    maxEdges = edgeCount[pos];
                }
            }
        }
        return n - maxEdges;
    }
};
